// DEM loader: samples elevation (meters) from a rescaled grayscale PNG heightmap.
// PNG covers Taiwan in EPSG:3826 (TWD97 TM2) meters; source lon/lat (WGS84) must be
// reprojected to TM2 before sampling.

const DEM_URL = 'data:image/png;base64,';
const EXTENT = { minX: 150970, minY: 2422070, maxX: 351670, maxY: 2799170 }; // EPSG:3826 meters
const ELEV = { min: -2.7166731358, max: 3716.4968261719 };

// GRS80 ellipsoid, TWD97 TM2 (EPSG:3826): lon0=121E, k0=0.9999, FE=250000, FN=0
function lonLatToTWD97(lonDeg, latDeg) {
  const a = 6378137.0;
  const f = 1 / 298.257222101;
  const k0 = 0.9999;
  const lon0 = (121 * Math.PI) / 180;
  const FE = 250000, FN = 0;
  const e2 = f * (2 - f);
  const ep2 = e2 / (1 - e2);
  const lat = (latDeg * Math.PI) / 180;
  const lon = (lonDeg * Math.PI) / 180;
  const sinLat = Math.sin(lat), cosLat = Math.cos(lat), tanLat = Math.tan(lat);
  const N = a / Math.sqrt(1 - e2 * sinLat * sinLat);
  const T = tanLat * tanLat;
  const C = ep2 * cosLat * cosLat;
  const A = (lon - lon0) * cosLat;
  const M = a * (
    (1 - e2 / 4 - (3 * e2 * e2) / 64 - (5 * e2 * e2 * e2) / 256) * lat -
    ((3 * e2) / 8 + (3 * e2 * e2) / 32 + (45 * e2 * e2 * e2) / 1024) * Math.sin(2 * lat) +
    ((15 * e2 * e2) / 256 + (45 * e2 * e2 * e2) / 1024) * Math.sin(4 * lat) -
    ((35 * e2 * e2 * e2) / 3072) * Math.sin(6 * lat)
  );
  const x = FE + k0 * N * (A + ((1 - T + C) * A ** 3) / 6 + ((5 - 18 * T + T * T + 72 * C - 58 * ep2) * A ** 5) / 120);
  const y = FN + k0 * (M + N * tanLat * (A ** 2 / 2 + ((5 - T + 9 * C + 4 * C * C) * A ** 4) / 24 + ((61 - 58 * T + T * T + 600 * C - 330 * ep2) * A ** 6) / 720));
  return { x, y };
}

export const NODATA_ELEV = ELEV.min;
export { lonLatToTWD97 };

// Inverse of lonLatToTWD97 (Snyder's inverse transverse-Mercator formulas), used to plot the
// county-boundary GeoJSON (stored in TWD97 TM2 meters) back into the scene's lon/lat-based frame.
function twd97ToLonLat(x, y) {
  const a = 6378137.0;
  const f = 1 / 298.257222101;
  const k0 = 0.9999;
  const lon0 = (121 * Math.PI) / 180;
  const FE = 250000, FN = 0;
  const e2 = f * (2 - f);
  const e1 = (1 - Math.sqrt(1 - e2)) / (1 + Math.sqrt(1 - e2));
  const ep2 = e2 / (1 - e2);
  const M = (y - FN) / k0;
  const mu = M / (a * (1 - e2 / 4 - (3 * e2 * e2) / 64 - (5 * e2 * e2 * e2) / 256));
  const phi1 = mu
    + ((3 * e1) / 2 - (27 * e1 ** 3) / 32) * Math.sin(2 * mu)
    + ((21 * e1 * e1) / 16 - (55 * e1 ** 4) / 32) * Math.sin(4 * mu)
    + ((151 * e1 ** 3) / 96) * Math.sin(6 * mu)
    + ((1097 * e1 ** 4) / 512) * Math.sin(8 * mu);
  const sinPhi1 = Math.sin(phi1), cosPhi1 = Math.cos(phi1), tanPhi1 = Math.tan(phi1);
  const C1 = ep2 * cosPhi1 * cosPhi1;
  const T1 = tanPhi1 * tanPhi1;
  const N1 = a / Math.sqrt(1 - e2 * sinPhi1 * sinPhi1);
  const R1 = (a * (1 - e2)) / Math.pow(1 - e2 * sinPhi1 * sinPhi1, 1.5);
  const D = (x - FE) / (N1 * k0);
  const lat = phi1 - ((N1 * tanPhi1) / R1) * (
    D ** 2 / 2
    - ((5 + 3 * T1 + 10 * C1 - 4 * C1 * C1 - 9 * ep2) * D ** 4) / 24
    + ((61 + 90 * T1 + 298 * C1 + 45 * T1 * T1 - 252 * ep2 - 3 * C1 * C1) * D ** 6) / 720
  );
  const lon = lon0 + (
    D
    - ((1 + 2 * T1 + C1) * D ** 3) / 6
    + ((5 - 2 * C1 + 28 * T1 - 3 * C1 * C1 + 8 * ep2 + 24 * T1 * T1) * D ** 5) / 120
  ) / cosPhi1;
  return { lon: (lon * 180) / Math.PI, lat: (lat * 180) / Math.PI };
}
export { twd97ToLonLat };

export async function loadDEM() {
  const img = await new Promise((resolve, reject) => {
    const im = new Image();
    im.onload = () => resolve(im);
    im.onerror = () => reject(new Error('DEM image failed to load: ' + DEM_URL));
    im.src = DEM_URL;
  });
  const canvas = document.createElement('canvas');
  canvas.width = img.width;
  canvas.height = img.height;
  const ctx = canvas.getContext('2d');
  ctx.drawImage(img, 0, 0);
  const { data } = ctx.getImageData(0, 0, img.width, img.height);
  const w = img.width, h = img.height;

  function grayAt(col, row) {
    col = Math.min(w - 1, Math.max(0, col));
    row = Math.min(h - 1, Math.max(0, row));
    const idx = (row * w + col) * 4;
    return data[idx]; // R channel (grayscale, R=G=B)
  }

  function sample(lon, lat) {
    const { x, y } = lonLatToTWD97(lon, lat);
    // outside the DEM's real coverage (open ocean / off-island) -> sea level, not a clamped-edge repeat
    if (x < EXTENT.minX || x > EXTENT.maxX || y < EXTENT.minY || y > EXTENT.maxY) return 0;
    const fc = ((x - EXTENT.minX) / (EXTENT.maxX - EXTENT.minX)) * (w - 1);
    const fr = ((EXTENT.maxY - y) / (EXTENT.maxY - EXTENT.minY)) * (h - 1);
    const c0 = Math.floor(fc), r0 = Math.floor(fr);
    const tc = fc - c0, tr = fr - r0;
    const g00 = grayAt(c0, r0), g10 = grayAt(c0 + 1, r0);
    const g01 = grayAt(c0, r0 + 1), g11 = grayAt(c0 + 1, r0 + 1);
    const gray = g00 * (1 - tc) * (1 - tr) + g10 * tc * (1 - tr) + g01 * (1 - tc) * tr + g11 * tc * tr;
    return ELEV.min + (gray / 255) * (ELEV.max - ELEV.min);
  }

  return { sample };
}

window.__demModule = { loadDEM, NODATA_ELEV, lonLatToTWD97, twd97ToLonLat };
